import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int left = in.nextInt(), right = in.nextInt(), count = 0;
        for (int v = left; v <= right; v++) {
            int a = v / 100, b = v / 10 % 10, c = v % 10;
            if (a != b && a != c && b != c) count++;
        }
        System.out.println(count);
    }
}

package main

import "fmt"

func main() {
	var left, right int
	fmt.Scan(&left, &right)
	count := 0
	for v := left; v <= right; v++ {
		a, b, c := v/100, v/10%10, v%10
		if a != b && a != c && b != c {
			count++
		}
	}
	fmt.Println(count)
}
